// Голосовые из чатов: один факт вместо двух.
//
// Пункт 8 документа otkazy-reshennoe-v-spin.md. Что было: пакет вклеивает расшифровку
// голосового прямо в текст сообщения («<имя файла>.ogg\n\n[Голосовое сообщение]: …»),
// а сборщик фактов из того же сообщения делал ДВА факта — `chat` с этим текстом и ещё
// `chat_voice_transcript` с той же расшифровкой, только с префиксом роли. Журнал тоже
// печатал расшифровку второй раз, отдельным блоком «--- Транскрипт голосового ---».
//
// По базе за 60 дней: 6 разборов с голосовыми, 28 фактов — и все 28 оказались дублями,
// лишних 7 899 символов. Судья видел одну и ту же фразу клиента дважды и мог считать её
// двумя разными репликами.
//
// Как в СПИН (Ф2б): сообщение с голосовым даёт один факт `chat_voice_transcript`
// (текст уже слит пакетом), сообщение без голосового — один факт `chat`.
//
// Источник правок — этот файл. Моки: tests/chat-voice/run.js

// Признак того, что в сообщении было голосовое. Поле transcript ставит пакет при удачном
// распознавании; _has_audio_transcript — тот же признак, по нему пакет оставляет сообщение
// в выборке, даже если текста у него не было вовсе.
function chatHasVoice(comm) {
  var c = comm || {};
  if (c._has_audio_transcript === true) return true;
  return !!(c.transcript && String(c.transcript).trim().length > 0);
}

// Источник факта для сообщения чата.
function chatFactSource(comm) {
  return chatHasVoice(comm) ? 'chat_voice_transcript' : 'chat';
}

// Имя файла голосового, которое пакет приклеивает первой строкой. Судье оно не нужно:
// это внутренний идентификатор, а в факте он читается как часть сообщения.
var CHAT_VOICE_FILE_RE = /^\s*[0-9a-f-]{8,}\.(ogg|oga|opus|mp3|mpga|m4a|wav)\s*\n+/i;

// Текст факта: слитый пакетом текст сообщения без имени файла.
function chatFactContent(comm) {
  var c = comm || {};
  var txt = String(c.text || '');
  txt = txt.replace(CHAT_VOICE_FILE_RE, '');
  return txt.trim();
}
